package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.ConfigOverride;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_createBeanDeserializer_TriageGen1Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private DeserializationConfig config;
    private JavaType type;
    private BeanDescription beanDesc;
    private TypeFactory typeFactory;

    // A dummy class to represent a potential bean
    public static class TestBean {
        public String name;
    }

    // A dummy abstract class
    public static abstract class AbstractBean {
        public String id;
    }

    // A dummy throwable
    public static class TestException extends RuntimeException {}

    @Before
    public void setUp() {
        // BeanDeserializerFactory constructor requires DeserializerFactoryConfig
        // Using null or mock if the constructor allows, but since we are testing 
        // the logic of the method, we will spy on the factory to mock protected methods.
        factory = spy(new BeanDeserializerFactory(null));
        ctxt = mock(DeserializationContext.class);
        config = mock(DeserializationConfig.class);
        typeFactory = TypeFactory.defaultInstance();

        when(ctxt.getConfig()).thenReturn(config);

        type = typeFactory.constructType(TestBean.class);
        beanDesc = mock(BeanDescription.class);
    }

    @Test
    public void testCreateBeanDeserializer_CustomOverrideFound() throws JsonMappingException {
        JsonDeserializer<Object> customDeser = mock(JsonDeserializer.class);
        doReturn(customDeser).when(factory)._findCustomBeanDeserializer(any(), any(), any());

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(customDeser, result);
        verify(factory, never()).buildThrowableDeserializer(any(), any(), any());
    }

    @Test
    public void testCreateBeanDeserializer_IsThrowable() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        JavaType throwableType = typeFactory.constructType(TestException.class);
        JsonDeserializer<Object> throwableDeser = mock(JsonDeserializer.class);

        doReturn(throwableDeser).when(factory).buildThrowableDeserializer(ctxt, throwableType, beanDesc);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, throwableType, beanDesc);

        assertEquals(throwableDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_MaterializeAbstractType() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());

        // Setup abstract type
        JavaType abstractType = typeFactory.constructType(AbstractBean.class);
        JavaType concreteType = typeFactory.constructType(TestBean.class);
        JsonDeserializer<Object> concreteDeser = mock(JsonDeserializer.class);
        BeanDescription newBeanDesc = mock(BeanDescription.class);

        doReturn(concreteType).when(factory).materializeAbstractType(ctxt, abstractType, beanDesc);
        doReturn(config).when(config).introspect(concreteType);
        doReturn(newBeanDesc).when(config).introspect(concreteType);
        doReturn(concreteDeser).when(factory).buildBeanDeserializer(ctxt, concreteType, newBeanDesc);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, abstractType, beanDesc);

        assertEquals(concreteDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_StandardDeserializerFound() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        // Ensure it's not throwable and not abstract to pass previous checks
        JsonDeserializer<Object> stdDeser = mock(JsonDeserializer.class);
        doReturn(stdDeser).when(factory).findStdDeserializer(ctxt, type, beanDesc);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(stdDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_NotPotentialBeanType() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        doReturn(null).when(factory).findStdDeserializer(ctxt, type, beanDesc);

        // Use a type that is not a potential bean (e.g., String)
        JavaType stringType = typeFactory.constructType(String.class);
        doReturn(false).when(factory).isPotentialBeanType(String.class);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, stringType, beanDesc);

        assertNull(result);
    }

    @Test
    public void testCreateBeanDeserializer_BuildBeanDeserializer() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        doReturn(null).when(factory).findStdDeserializer(ctxt, type, beanDesc);
        doReturn(true).when(factory).isPotentialBeanType(TestBean.class);

        JsonDeserializer<Object> beanDeser = mock(JsonDeserializer.class);
        doReturn(beanDeser).when(factory).buildBeanDeserializer(ctxt, type, beanDesc);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(beanDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_AbstractType_NotMaterializable() throws JsonMappingException {
        doReturn(null).when(factory)._findCustomBeanDeserializer(any(), any(), any());
        JavaType abstractType = typeFactory.constructType(AbstractBean.class);

        doReturn(null).when(factory).materializeAbstractType(ctxt, abstractType, beanDesc);
        doReturn(null).when(factory).findStdDeserializer(ctxt, abstractType, beanDesc);
        doReturn(false).when(factory).isPotentialBeanType(AbstractBean.class);

        JsonDeserializer<Object> result = factory.createBeanDeserializer(ctxt, abstractType, beanDesc);

        assertNull(result);
    }
}
